const { useState, useRef, useEffect, useCallback, createContext, useContext } = React;

// ── Almacenamiento persistente (IndexedDB) ─────────────────────
// Antes esta app guardaba todo en localStorage, que tiene un límite real
// de ~5-10MB por sitio/app y puede perderse fácil (modo incógnito,
// navegadores "in-app" de WhatsApp/Instagram, límites de Safari, etc.).
//
// Ahora usamos IndexedDB como almacén real: el límite pasa a ser
// gigabytes (un % del disco libre del dispositivo), suficiente para
// miles de comidas, vitaminas, rutinas, fotos de progreso, etc.
//
// Para no reescribir toda la app (que usa un hook `usePersist` síncrono,
// como localStorage), mantenemos una caché en memoria que se hidrata UNA
// vez desde IndexedDB antes de mostrar la app (ver `mfHydrate` más abajo).
// A partir de ahí, cada lectura es instantánea (memoria) y cada escritura
// se guarda en memoria al instante Y se envía a IndexedDB en segundo
// plano, así nunca se pierde nada aunque la pantalla se cierre rápido.
const MF_DB_NAME = "macrosfit_db";
const MF_STORE = "kv";
const cache = {};
let dbPromise = null;
let hydrated = false;
let hydrationPromise = null;

function mfOpenDB() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve) => {
    if (!("indexedDB" in window)) { resolve(null); return; }
    try {
      const req = window.indexedDB.open(MF_DB_NAME, 1);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(MF_STORE)) db.createObjectStore(MF_STORE);
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    } catch { resolve(null); }
  });
  return dbPromise;
}

function mfWriteIDB(key, value) {
  mfOpenDB().then((db) => {
    if (!db) return;
    try { db.transaction(MF_STORE, "readwrite").objectStore(MF_STORE).put(value, key); } catch {}
  });
}

function mfDeleteIDB(key) {
  mfOpenDB().then((db) => {
    if (!db) return;
    try { db.transaction(MF_STORE, "readwrite").objectStore(MF_STORE).delete(key); } catch {}
  });
}

// Carga todo lo que haya en IndexedDB a la caché en memoria, y además
// migra (una sola vez) cualquier dato viejo que solo exista en
// localStorage, para que nadie pierda su progreso al actualizar la app.
function mfHydrate() {
  if (hydrationPromise) return hydrationPromise;
  hydrationPromise = (async () => {
    const db = await mfOpenDB();
    if (db) {
      await new Promise((resolve) => {
        try {
          const store = db.transaction(MF_STORE, "readonly").objectStore(MF_STORE);
          const req = store.openCursor();
          req.onsuccess = (e) => {
            const cursor = e.target.result;
            if (cursor) { cache[cursor.key] = cursor.value; cursor.continue(); }
            else resolve();
          };
          req.onerror = () => resolve();
        } catch { resolve(); }
      });
    }
    try {
      for (let i = 0; i < window.localStorage.length; i++) {
        const k = window.localStorage.key(i);
        if (k && k.startsWith("mf_") && !(k in cache)) {
          const v = window.localStorage.getItem(k);
          cache[k] = v;
          mfWriteIDB(k, v);
        }
      }
    } catch {}
    hydrated = true;
  })();
  return hydrationPromise;
}

const memStorage = {
  getItem: (key) => (Object.prototype.hasOwnProperty.call(cache, key) ? cache[key] : null),
  setItem: (key, value) => {
    const v = String(value);
    cache[key] = v;
    mfWriteIDB(key, v);
    // Red de seguridad extra para navegadores muy viejos sin IndexedDB;
    // IndexedDB es ahora la fuente de verdad y no tiene este límite de tamaño.
    try { window.localStorage.setItem(key, v); } catch {}
  },
  removeItem: (key) => {
    delete cache[key];
    mfDeleteIDB(key);
    try { window.localStorage.removeItem(key); } catch {}
  },
};

// Devuelve todas las claves de la app guardadas (para exportar backup)
function mfAllKeys() {
  return Object.keys(cache).filter(k => k.startsWith("mf_"));
}

// Descarga un archivo .json con TODOS los datos de la app (vitaminas,
// comidas, rutinas, fotos, perfil, etc.) para que el usuario pueda
// guardarlo donde quiera y restaurarlo en cualquier dispositivo.
// Detecta si estamos corriendo dentro de la app instalada (APK/Capacitor)
// en lugar del navegador (Netlify / testing web).
function mfIsNative() {
  try {
    return !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  } catch { return false; }
}

// Exporta un archivo .json con TODOS los datos de la app (vitaminas,
// comidas, rutinas, fotos, perfil, etc.).
//
// IMPORTANTE: en la app instalada (APK), el truco viejo de blob + <a
// download> NO es confiable: el WebView de Android no tiene forma de
// guardar ese blob en el sistema de archivos real, así que a veces
// "funciona" la primera vez por casualidad y luego se queda pegado sin
// descargar nada. Por eso, dentro de la app usamos los plugins nativos
// de Capacitor (Filesystem + Share), que sí escriben un archivo real y
// abren el selector nativo para guardarlo/compartirlo, cada vez.
// En el navegador seguimos usando blob + <a download>, que ahí es 100% confiable.
async function mfExportBackup() {
  const data = {};
  mfAllKeys().forEach(k => { data[k] = cache[k]; });
  const payload = { app: "MacrosFit", exportedAt: new Date().toISOString(), data };
  const json = JSON.stringify(payload);
  const filename = `macrosfit-backup-${new Date().toISOString().slice(0,10)}.json`;

  if (mfIsNative()) {
    const Plugins = window.Capacitor.Plugins || {};
    const { Filesystem, Share } = Plugins;
    if (Filesystem && Share) {
      try {
        const written = await Filesystem.writeFile({
          path: filename,
          data: json,
          directory: "CACHE",
          encoding: "utf8",
        });
        await Share.share({
          title: "Copia de seguridad MacrosFit",
          text: "Copia de seguridad de tus datos de MacrosFit",
          url: written.uri,
          dialogTitle: "Guardar copia de seguridad",
        });
        return true;
      } catch (e) {
        console.error("Error exportando (nativo):", e);
        // si el camino nativo falla (p.ej. plugins no instalados), probamos el método web como último recurso
      }
    }
  }

  try {
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    return true;
  } catch (e) {
    console.error("Error exportando (web):", e);
    return false;
  }
}

// Lee un archivo .json exportado previamente y restaura todos los datos.
function mfImportBackup(file, onDone, onError) {
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const parsed = JSON.parse(reader.result);
      const data = parsed && parsed.data ? parsed.data : parsed;
      if (!data || typeof data !== "object") throw new Error("formato inválido");
      Object.keys(data).forEach(k => {
        if (k.startsWith("mf_")) memStorage.setItem(k, data[k]);
      });
      onDone && onDone();
    } catch (e) {
      onError && onError(e);
    }
  };
  reader.onerror = () => onError && onError(new Error("no se pudo leer el archivo"));
  reader.readAsText(file);
}

// ── Sonido de alarma y notificaciones reales ───────────────────
// Genera el "beep" con Web Audio (no depende de archivos de audio) y
// dispara notificaciones del sistema. Los navegadores exigen un gesto
// del usuario (un toque en pantalla) antes de poder reproducir audio,
// por eso `mfUnlockAudio` se llama en el primer toque de toda la app.
let mfAudioCtx = null;
function mfGetAudioCtx() {
  if (!mfAudioCtx) {
    try { mfAudioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch { mfAudioCtx = null; }
  }
  return mfAudioCtx;
}
function mfUnlockAudio() {
  const ctx = mfGetAudioCtx();
  if (ctx && ctx.state === "suspended") ctx.resume().catch(()=>{});
}
function mfPlayAlarmSound() {
  const ctx = mfGetAudioCtx();
  if (!ctx) return;
  if (ctx.state === "suspended") ctx.resume().catch(()=>{});
  const beepAt = (startDelay) => {
    try {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.value = 880;
      gain.gain.setValueAtTime(0, ctx.currentTime + startDelay);
      gain.gain.linearRampToValueAtTime(0.35, ctx.currentTime + startDelay + 0.02);
      gain.gain.linearRampToValueAtTime(0, ctx.currentTime + startDelay + 0.3);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(ctx.currentTime + startDelay);
      osc.stop(ctx.currentTime + startDelay + 0.32);
    } catch {}
  };
  [0, 0.42, 0.84].forEach(beepAt);
}
function mfRequestNotifPermission() {
  if (typeof Notification!=="undefined" && Notification.permission==="default") {
    Notification.requestPermission().catch(()=>{});
  }
}
// mode: "alarm" (sonido + notificación), "notif" (solo notificación), "off" (nada)
function mfSendReminder(mode, title, body) {
  if (!mode || mode === "off") return;
  if (mode === "alarm") mfPlayAlarmSound();
  if (typeof Notification!=="undefined" && Notification.permission==="granted") {
    try { new Notification(title, { body }); } catch {}
  }
}
// Determina el modo (alarma/notificación/ninguna) de una categoría, con
// compatibilidad hacia atrás: si el perfil aún no tiene el campo "...Mode"
// (perfiles guardados antes de este cambio), se deduce del interruptor viejo.
function mfModeOf(profileObj, key) {
  const p = profileObj || {};
  if (p[key+"Mode"]) return p[key+"Mode"];
  return p[key] === false ? "off" : "alarm";
}

// ── Color automático por rutina (Seguimiento) ──────────────────
// Cada rutina recibe un color estable de una paleta fija, calculado a
// partir de su id (mismo id → siempre el mismo color, sin tener que
// guardarlo aparte ni que el usuario lo elija).
const MF_ROUTINE_COLORS = ["#FF6B52","#4D9DE0","#22C55E","#A78BFA","#F59E0B","#EC4899","#14B8A6","#EF4444","#6366F1","#84CC16"];
function mfRoutineColor(routineId) {
  const s = String(routineId);
  let hash = 0;
  for (let i=0;i<s.length;i++){ hash = (hash*31 + s.charCodeAt(i)) >>> 0; }
  return MF_ROUTINE_COLORS[hash % MF_ROUTINE_COLORS.length];
}
function mfFormatWorkoutDuration(ms) {
  const totalMin = Math.max(0, Math.round(ms/60000));
  const h = Math.floor(totalMin/60), m = totalMin%60;
  return h>0 ? `${h}h ${m}m` : `${m}m`;
}
// ── Datos por serie (reps/peso individuales) ────────────────────
// Devuelve un arreglo de {reps, weight} del largo indicado por "series".
// Si el ejercicio todavía no tiene datos por serie guardados (ejercicios
// creados antes de este cambio), no inventa valores — deja las filas vacías
// para que el usuario las llene desde "Metas".
function mfGetSeriesData(ex) {
  const n = Math.max(0, parseInt(ex?.series) || 0);
  return Array.from({ length: n }, (_, i) =>
    (ex?.seriesData && ex.seriesData[i]) ? ex.seriesData[i] : { reps:"", weight:"" }
  );
}
// Combina los valores de todas las series en un solo texto para la tarjeta:
// si todas son iguales, muestra un solo número; si son distintas, las junta
// con "/" (ej. "11/12/13"), sin cambiar el tamaño del cuadro.
function mfCombineSeriesValues(values, suffix) {
  const clean = values.filter(v => v !== undefined && v !== null && v !== "");
  if (clean.length === 0) return "—";
  const allSame = clean.every(v => String(v) === String(clean[0]));
  return allSame ? `${clean[0]}${suffix||""}` : clean.join("/");
}

// ── Puente a notificaciones nativas (solo existe dentro del APK) ──
// Cuando la app corre empaquetada con Capacitor, el propio Capacitor
// inyecta "window.Capacitor.Plugins.LocalNotifications" en la página,
// sin necesitar ningún import especial. Si esto existe, programamos las
// alarmas directamente en el sistema operativo (persisten aunque cierres
// la app o bloquees el celular). Si no existe (o sea, esto sigue siendo
// la página web normal en Netlify), no hace nada y se usa el motor de
// recordatorios basado en el navegador.
function mfHasNative() {
  return !!(window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications);
}

async function mfSyncNativeAlarms() {
  if (!mfHasNative()) return;
  const LN = window.Capacitor.Plugins.LocalNotifications;

  try {
    const perm = await LN.checkPermissions();
    if (perm.display !== "granted") {
      const req = await LN.requestPermissions();
      if (req.display !== "granted") return;
    }
  } catch {}

  // Cancela lo programado en una sincronización anterior, para no duplicar
  try {
    const prevIdsRaw = memStorage.getItem("mf_native_ids");
    const prevIds = prevIdsRaw ? JSON.parse(prevIdsRaw) : [];
    if (prevIds.length) await LN.cancel({ notifications: prevIds.map(id => ({ id })) });
  } catch {}

  let prof = {};
  try { prof = JSON.parse(memStorage.getItem("mf_profile") || "{}"); } catch {}
  let vitamins = [];
  try { vitamins = JSON.parse(memStorage.getItem("mf_vitamins") || "[]"); } catch {}

  const toSchedule = [];
  let nextId = 1000;
  const push = (title, body, hour, minute, weekday) => {
    const sched = { on: { hour, minute: minute || 0, allowWhileIdle: true }, repeats: true };
    if (weekday != null) sched.on.weekday = weekday;
    // smallIcon/iconColor por notificación: respaldo por si el valor por defecto
    // definido en capacitor.config.json (plugins.LocalNotifications) no se
    // aplica en algún dispositivo. Debe existir el recurso nativo
    // android/app/src/main/res/drawable-*/ic_stat_macrosfit.png (silueta blanca)
    // para que Android deje de mostrar el ícono de "¡" por defecto.
    toSchedule.push({
      id: nextId++, title, body, schedule: sched,
      smallIcon: "ic_stat_macrosfit",
      iconColor: "#F97316",
    });
  };

  // 💧 Agua — cada 1h/2h/3h, de 8:00 am a 9:00 pm
  if (mfModeOf(prof, "notifWater") !== "off") {
    const step = prof.notifWaterHrs || 2;
    for (let h = 8; h <= 21; h += step) {
      push("💧 Hora de hidratarte", "Toma un vaso de agua para seguir tu meta de hoy.", h, 0);
    }
  }

  // 🍽️ Comidas — la lista editable en Mi perfil
  if (mfModeOf(prof, "notifMeals") !== "off" && Array.isArray(prof.mealAlarms)) {
    prof.mealAlarms.forEach(a => {
      if (!a.time) return;
      const [h, m] = a.time.split(":").map(Number);
      push("🍽️ " + (a.label || "Comida"), `Es hora de ${a.label || "tu comida"} (${a.time}).`, h, m);
    });
  }

  // 😴 Sueño
  if (mfModeOf(prof, "notifSleep") !== "off" && prof.notifSleepHrs) {
    const [h, m] = prof.notifSleepHrs.split(":").map(Number);
    if (!Number.isNaN(h)) push("😴 Hora de dormir", "Prepárate para descansar y registra tu sueño de hoy.", h, m);
  }

  // 🏋️ Entrenamiento
  if (mfModeOf(prof, "notifTraining") !== "off" && prof.notifTrainingHrs) {
    const [h, m] = prof.notifTrainingHrs.split(":").map(Number);
    if (!Number.isNaN(h)) push("🏋️ Hora de entrenar", "Toca para ver tu rutina de hoy.", h, m);
  }

  // 💊 Vitaminas — una entrada por cada día de la semana seleccionado
  if (mfModeOf(prof, "notifVitamins") !== "off") {
    vitamins.forEach(v => {
      if (!v.alarm) return;
      const [h, m] = v.alarm.split(":").map(Number);
      const days = (v.days && v.days.length) ? v.days : [0,1,2,3,4,5,6];
      days.forEach(wd => push(
        "💊 Hora de tu vitamina",
        `${v.name} — ${v.pills} pastilla${v.pills!=1?"s":""} (${v.mg} mg)`,
        h, m, wd + 1 // Capacitor usa 1=domingo...7=sábado
      ));
    });
  }

  try {
    if (toSchedule.length) await LN.schedule({ notifications: toSchedule });
    memStorage.setItem("mf_native_ids", JSON.stringify(toSchedule.map(n => n.id)));
  } catch (e) {
    console.error("No se pudieron programar las alarmas nativas", e);
  }
}
// ── Cálculo preciso de macros (sin redondeo acumulado) ─────────
// Redondea a 2 decimales de forma correcta (evitando el clásico error de
// coma flotante donde p.ej. 1.005 se puede convertir en 1.00 en vez de 1.01).
function mfRound2(n) {
  if (!Number.isFinite(n)) return 0;
  return Math.round((n + Number.EPSILON) * 100) / 100;
}

// Suma las kcal/proteína/carbos/grasas de una lista de alimentos con
// cantidades, y SOLO redondea al final (no en cada paso). Redondear en
// cada suma parcial es lo que causaba desfases (ej. varios alimentos con
// 0.1/3.9/etc. que al ir redondeando de a uno terminan sumando mal).
function mfSumFoodPortions(items) {
  const raw = (items || []).reduce((a, it) => {
    const baseQty = it.qty || 100;
    const ratio = (it.grams != null ? it.grams : baseQty) / (baseQty || 100);
    return {
      kcal: a.kcal + (Number(it.kcal) || 0) * ratio,
      p:    a.p    + (Number(it.p)    || 0) * ratio,
      c:    a.c    + (Number(it.c)    || 0) * ratio,
      g:    a.g    + (Number(it.g)    || 0) * ratio,
    };
  }, { kcal: 0, p: 0, c: 0, g: 0 });
  return { kcal: mfRound2(raw.kcal), p: mfRound2(raw.p), c: mfRound2(raw.c), g: mfRound2(raw.g) };
}

// Calcula el total nutricional de una comida guardada (meal.foods) usando
// SIEMPRE los valores actuales del alimento en la lista de "Alimentos" si
// todavía existe (así, si el usuario corrige los macros de un alimento
// después, las comidas que lo usan se actualizan solas). Si el alimento ya
// fue borrado, usa como respaldo los valores que se guardaron al crear la
// comida (snapshot), para no perder el dato.
function mfComputeMealTotal(mealFoods, currentFoods) {
  const byId = {};
  (currentFoods || []).forEach(cf => { byId[cf.id] = cf; });
  const items = (mealFoods || []).map(f => {
    const current = byId[f.id];
    const src = current || f;
    return { kcal: src.kcal, p: src.p, c: src.c, g: src.g, qty: src.qty, grams: f.grams };
  });
  return mfSumFoodPortions(items);
}

// Redimensiona cualquier foto que suba el usuario (perfil, alimentos,
// vitaminas, comidas, ejercicios) ANTES de guardarla. Las fotos de cámara
// vienen en resolución muy alta (varios MB); mostrar eso directo en un
// ícono/miniatura chica es lo que causaba que se viera "con zoom" un
// instante mientras el celular terminaba de procesar la imagen completa,
// hasta que se acomodaba sola. onDone recibe siempre un resultado (si algo
// falla, cae de vuelta a la imagen original sin redimensionar).
function mfResizeImage(dataUrl, maxDim, quality, onDone) {
  try {
    const img = new Image();
    img.onload = () => {
      let w = img.width, h = img.height;
      if (w > h && w > maxDim) { h = Math.round(h*(maxDim/w)); w = maxDim; }
      else if (h >= w && h > maxDim) { w = Math.round(w*(maxDim/h)); h = maxDim; }
      try {
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, w, h);
        onDone(canvas.toDataURL("image/jpeg", quality));
      } catch { onDone(dataUrl); }
    };
    img.onerror = () => onDone(dataUrl);
    img.src = dataUrl;
  } catch { onDone(dataUrl); }
}
// Convierte una hora guardada en formato 24h "HH:MM" a texto legible en 12h
// con AM/PM completo (ej. "3:00 PM"), para mostrarla en pantalla. El valor
// interno de los <input type="time"> sigue siendo 24h (lo exige el estándar),
// esto solo cambia cómo se ve el texto ya guardado.
function fmtTime12(hhmm) {
  if (!hhmm || typeof hhmm !== "string" || !hhmm.includes(":")) return hhmm || "";
  const [h, m] = hhmm.split(":").map(Number);
  if (Number.isNaN(h) || Number.isNaN(m)) return hhmm;
  const period = h < 12 ? "AM" : "PM";
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(m).padStart(2,"0")} ${period}`;
}

