const BODY_VIEWBOX = {
  maleFront:   "0 95 727 1280",
  maleBack:    "718 95 727 1280",
  femaleFront: "0 0 650 1450",
  femaleBack:  "823 0 650 1450",
};

// Músculo (nombre en la app) -> slug del mapa corporal
const MUSCLE_TO_SLUG = {
  "Abdomen":"abs", "Pectoral":"chest", "Hombro":"deltoids", "Tríceps":"triceps",
  "Bíceps":"biceps", "Antebrazo":"forearm", "Cuádriceps":"quadriceps",
  "Pantorrilla":"calves", "Femoral":"hamstring", "Glúteo":"gluteal",
  "Dorsales":"upperBack", "Trapecio":"trapezius",
};

// Slug vecino que se ilumina junto con el slug principal (misma zona / músculo relacionado)
const SLUG_COMPANIONS = {
  "upperBack":  ["lowerBack"],   // Dorsales -> también espalda baja
  "abs":        ["obliques"],    // Abdomen -> también oblicuos
  "quadriceps": ["adductors"],   // Cuádriceps -> también aductores
  "calves":     ["tibialis"],    // Pantorrilla -> también tibial anterior
};

function MuscleBodyMap({ gender="male", view="front", colorFor, neutral="#D7DBE3" }) {
  const key = gender + (view==="front" ? "Front" : "Back");
  const paths = BODY_PATHS[key] || {};
  const viewBox = BODY_VIEWBOX[key];
  return (
    <svg viewBox={viewBox} style={{ width:"100%",height:"100%",display:"block" }}>
      {Object.entries(paths).map(([slug, sides]) => {
        const fill = colorFor(slug) || neutral;
        return (
          <g key={slug}>
            {sides.left.map((d,i) => <path key={"l"+i} d={d} fill={fill}/>)}
            {sides.right.map((d,i) => <path key={"r"+i} d={d} fill={fill}/>)}
          </g>
        );
      })}
    </svg>
  );
}


function FatigueModal({ onClose, timestamps, setTimestamps, theme=0, bgTheme=0 }) {
  const [selected, setSelected] = useState(null);
  // tick every second for live countdown
  const [, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick(t => t+1), 1000);
    return () => clearInterval(id);
  }, []);

  const saveTimestamp = (name, ts) => {
    setTimestamps(t => ({ ...t, [name]: ts }));
    setSelected(null);
  };

  return (
    <>
      <Sheet onClose={onClose} maxH="92vh" theme={theme} bgTheme={bgTheme}>
        <SheetHeader title="Fatiga muscular" sub="Toca un músculo para actualizar su estado." onClose={onClose} theme={theme}/>
        <div style={{ overflowY:"auto",flex:1 }}>
          {MUSCLES.map(m => {
            const ts   = timestamps[m.name];
            const secs = ts !== undefined ? getSecsElapsed(ts) : null;
            const { color, label, pct } = secs !== null ? getStatus(secs) : { color:"#C4C9D4", label:"Sin registrar", pct:0 };
            const pctDisplay = Math.round(pct * 100);
            const countdown  = secs !== null ? formatCountdown(secs) : null;
            const done       = secs !== null && secs >= RECOVERY_HOURS * 3600;

            return (
              <div key={m.name} onClick={() => setSelected(m)}
                style={{ display:"flex",alignItems:"center",gap:12,padding:"12px 4px",borderBottom:"1px solid #F0F2F5",cursor:"pointer" }}>
                {/* emoji bubble */}
                <div style={{ width:42,height:42,borderRadius:"50%",background:`${color}18`,display:"flex",alignItems:"center",
                  justifyContent:"center",fontSize:20,flexShrink:0,filter:secs===null?"grayscale(1)":"none",overflow:"hidden" }}>
                  {m.image ? <img src={m.image} alt={m.name} style={{ width:"78%",height:"78%",objectFit:"contain" }}/> : m.emoji}
                </div>
                {/* center: name + countdown + bar */}
                <div style={{ flex:1,minWidth:0 }}>
                  <div style={{ fontWeight:700,fontSize:14,color:"#1E2A3A",marginBottom:3 }}>{m.name}</div>
                  {countdown && (
                    <div style={{ fontSize:13,fontWeight:800,color:done?"#22C55E":color,fontVariantNumeric:"tabular-nums",letterSpacing:0.5,marginBottom:4 }}>
                      {done ? "00:00:00 ✅" : `⏱ ${countdown}`}
                    </div>
                  )}
                  <div style={{ height:7,background:"#F0F2F5",borderRadius:99,overflow:"hidden" }}>
                    <div style={{ width:`${pctDisplay}%`,height:"100%",background:color,borderRadius:99 }}/>
                  </div>
                </div>
                {/* right: pct + label */}
                <div style={{ flexShrink:0,textAlign:"right",minWidth:74 }}>
                  {secs !== null && (
                    <div style={{ fontSize:14,fontWeight:900,color,lineHeight:1 }}>{pctDisplay}%</div>
                  )}
                  <div style={{ fontSize:11,fontWeight:700,color,marginTop:2 }}>{label}</div>
                </div>
              </div>
            );
          })}
          <div style={{ fontSize:11,color:"#C4C9D4",textAlign:"center",marginTop:14,paddingBottom:4 }}>
            Toca un músculo para registrar · 0-23h 🔴 · 24-67h 🟡 · 68h+ 🟢
          </div>
        </div>
      </Sheet>
      {selected && <MuscleSlider muscle={selected} onSave={saveTimestamp} onClose={()=>setSelected(null)} theme={theme}/>}
    </>
  );
}

// ── Calorie gauge ─────────────────────────────────────────────
function CalorieGauge({ consumed, goal }) {
  const pct=Math.min(consumed/goal,1), r=90, cx=120, cy=110;
  const C=Math.PI*r;
  return (
    <svg width="240" height="130" viewBox="0 0 240 130" style={{ width:"100%",maxWidth:240,height:"auto" }}>
      <defs><linearGradient id="gGrad" x1="0%" y1="0%" x2="100%" y2="0%"><stop offset="0%" stopColor="#4D9DE0"/><stop offset="100%" stopColor="#7ECBA1"/></linearGradient></defs>
      <path d={`M ${cx-r} ${cy} A ${r} ${r} 0 0 1 ${cx+r} ${cy}`} fill="none" stroke="#E8EDF5" strokeWidth="14" strokeLinecap="round"/>
      <path d={`M ${cx-r} ${cy} A ${r} ${r} 0 0 1 ${cx+r} ${cy}`} fill="none" stroke="url(#gGrad)" strokeWidth="14" strokeLinecap="round"
        strokeDasharray={C} strokeDashoffset={C*(1-pct)} style={{ transition:"stroke-dashoffset 0.6s ease" }}/>
      <circle cx={cx-r} cy={cy} r="7" fill="#4D9DE0"/>
    </svg>
  );
}

// ── Macro quick-add modal ─────────────────────────────────────
function MacroInputModal({ label, unit, color, bg, emoji, onAdd, onClose, theme=0, bgTheme=0 }) {
  const [val, setVal] = useState("");
  const [name, setName] = useState("");
  const valid = val !== "" && Number(val) > 0;
  const t = cardTheme(theme);
  return (
    <Sheet onClose={onClose} maxH="72vh" theme={theme} bgTheme={bgTheme}>
      <SheetHeader title={`Agregar ${label}`} sub={`Ingresa la cantidad en ${unit}`} onClose={onClose} theme={theme}/>
      <div style={{ overflowY:"auto",flex:1 }}>
      {/* Nombre opcional: si el alimento que consumiste no está guardado en
          la app, aquí puedes escribir qué fue, para que "Consumido hoy"
          muestre de qué se trata esa kcal/macro en vez de solo el número.
          No es obligatorio — sin nombre, se agrega igual. */}
      <div style={{ marginBottom:16 }}>
        <input type="text" value={name} onChange={e=>setName(e.target.value)}
          placeholder="¿Qué consumiste hoy? (opcional)"
          style={{ width:"100%",padding:"12px 14px",borderRadius:14,border:"1.5px solid transparent",
            background:false?"#F5F6FA":"rgba(120,120,120,0.15)",fontSize:14,fontWeight:600,
            color:false?"#1E2A3A":t.textColor,outline:"none",boxSizing:"border-box" }}/>
      </div>
      <div style={{ display:"flex",alignItems:"center",justifyContent:"center",gap:16,margin:"10px 0 20px" }}>
        <button onClick={()=>setVal(v=>String(Math.max(0,Number(v||0)-1)))}
          style={{ width:44,height:44,borderRadius:"50%",background:false?"#F0F2F5":"rgba(120,120,120,0.2)",border:"none",cursor:"pointer",fontSize:24,fontWeight:700,color:false?"#1E2A3A":t.textColor,display:"flex",alignItems:"center",justifyContent:"center" }}>−</button>
        <div style={{ textAlign:"center" }}>
          <div style={{ display:"flex",alignItems:"center",justifyContent:"center",gap:4 }}>
            <input type="number" value={val} onChange={e=>setVal(e.target.value)} placeholder="0"
              style={{ width:100,fontSize:40,fontWeight:900,color:false?"#1E2A3A":t.textColor,border:"none",textAlign:"center",background:"transparent",outline:"none" }}/>
            <span style={{ fontSize:18,color:false?"#9CA3AF":t.labelColor,fontWeight:600 }}>{unit}</span>
          </div>
          <div style={{ fontSize:13,color,fontWeight:700,marginTop:4 }}>{label}</div>
        </div>
        <button onClick={()=>setVal(v=>String(Number(v||0)+1))}
          style={{ width:44,height:44,borderRadius:"50%",background:bg,border:"none",cursor:"pointer",fontSize:24,fontWeight:700,color,display:"flex",alignItems:"center",justifyContent:"center" }}><img src={ICONS.masVerde} alt="+" style={{width:21,height:21,objectFit:"contain"}}/></button>
      </div>
      <div style={{ display:"flex",gap:8,marginBottom:20 }}>
        {(unit==="kcal"?[100,200,300,400,500]:[5,10,20,30,50]).map(v=>(
          <button key={v} onClick={()=>setVal(String(v))}
            style={{ flex:1,padding:"8px 0",borderRadius:12,border:"none",cursor:"pointer",fontSize:13,fontWeight:700,
              background:Number(val)===v?color:(false?"#F0F2F5":"rgba(120,120,120,0.2)"),color:Number(val)===v?"#fff":(false?"#6B7280":t.textColor) }}>
            {v}{unit==="kcal"?"":unit}
          </button>
        ))}
      </div>
      </div>
      <button onClick={()=>valid&&onAdd(Number(val), name.trim())}
        style={{ width:"100%",background:valid?color:"#C4C9D4",color:"#fff",border:"none",borderRadius:16,padding:"15px 0",fontSize:16,fontWeight:700,cursor:valid?"pointer":"default",flexShrink:0,marginTop:4 }}>
        Agregar {val||0} {unit}
      </button>
    </Sheet>
  );
}

// ── Macro row ─────────────────────────────────────────────────
function MacroRow({ emoji, image, label, color, value, goal, onAdd, theme=0, barVariant }) {
  const pct=Math.min((value/goal),1);
  const hex={pink:"#F472B6",orange:"#FBBF24",green:"#4ADE80"}[color];
  const bg ={pink:"#FFF0F6",orange:"#FFFBEB",green:"#F0FDF4"}[color];
  const dark = theme===1||theme===2;
  const accent = cardTheme(theme).accent;
  const valueColor = false ? "#1E2A3A" : (accent || "#fff");
  const subColor = false ? "#9CA3AF" : theme===3 ? "#9B9478" : "rgba(255,255,255,0.75)";
  const badge = badgeStyle(theme, bg);
  return (
    <div style={{ marginBottom:14 }}>
      <div style={{ display:"flex",alignItems:"center",gap:10 }}>
        <div style={{ width:44,height:44,borderRadius:"50%",background:badge.background,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,overflow:"hidden",flexShrink:0 }}>
          {image ? <img src={image} alt={label} style={{ width:"70%",height:"70%",objectFit:"contain",filter:badge.filter }}/> : emoji}
        </div>
        <div style={{ flex:1,minWidth:0 }}>
          <div style={{ fontWeight:700,fontSize:12,color:false?hex:theme===3?accent:"#fff",letterSpacing:0.5,textTransform:"uppercase" }}>{label}</div>
          <div style={{ fontWeight:800,fontSize:20,color:valueColor,lineHeight:1 }}>{mfRound2(value)}<span style={{ fontSize:13,fontWeight:500,color:subColor }}> g</span></div>
          <div style={{ fontSize:11,color:subColor }}>{Math.round(pct*100)}% / {goal}g</div>
        </div>
        <button onClick={onAdd} style={{ width:36,height:36,borderRadius:10,background:badge.background,border:"none",cursor:"pointer",fontSize:20,color:false?hex:(accent||"#fff"),display:"flex",alignItems:"center",justifyContent:"center",fontWeight:700,flexShrink:0 }}><img src={ICONS.masVerde} alt="+" style={{width:18,height:18,objectFit:"contain",filter:"none"}}/></button>
      </div>
      <div style={{ marginTop:6 }}>
        <ThemedBar theme={theme} pct={pct} color={false?hex:(accent||"#fff")} variant={barVariant}/>
      </div>
    </div>
  );
}

// ── Water bottle — redesigned with reference lines ────────────
function WaterBottle({ pct }) {
  // bottle body: top y=12, bottom y=148, inner height=136
  const bodyTop    = 12;
  const bodyBottom = 148;
  const innerH     = bodyBottom - bodyTop;   // 136
  const fillH      = Math.round(pct * innerH);
  const fillY      = bodyBottom - fillH;

  // reference lines at 25/50/75/100% from bottom
  const marks = [0.25, 0.50, 0.75, 1.00];

  return (
    <svg width="72" height="168" viewBox="0 0 72 168">
      <defs>
        <clipPath id="bottleClipNew">
          {/* rounded bottle shape */}
          <path d="M22 12 Q22 5 29 4 L43 4 Q50 5 50 12 L56 24 Q62 32 62 44 L62 136 Q62 148 52 150 L20 150 Q10 148 10 136 L10 44 Q10 32 16 24 Z"/>
        </clipPath>
        <linearGradient id="wGradNew" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#60C8F5" stopOpacity="0.9"/>
          <stop offset="100%" stopColor="#1A7EC8"/>
        </linearGradient>
        <linearGradient id="bottleBg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#E8F6FF"/>
          <stop offset="100%" stopColor="#D0EAFA"/>
        </linearGradient>
      </defs>

      {/* bottle body */}
      <path d="M22 12 Q22 5 29 4 L43 4 Q50 5 50 12 L56 24 Q62 32 62 44 L62 136 Q62 148 52 150 L20 150 Q10 148 10 136 L10 44 Q10 32 16 24 Z"
        fill="url(#bottleBg)" stroke="#A8D4F0" strokeWidth="1.5"/>

      {/* water fill */}
      <rect x="10" y={fillY} width="52" height={fillH}
        fill="url(#wGradNew)" clipPath="url(#bottleClipNew)"
        style={{ transition:"y 0.6s ease, height 0.6s ease" }}/>

      {/* shine overlay */}
      <rect x="14" y="44" width="8" height="80" rx="4"
        fill="white" opacity="0.18" clipPath="url(#bottleClipNew)"/>

      {/* reference tick marks — short horizontal lines on right side, no numbers */}
      {marks.map((m, i) => {
        const lineY = bodyBottom - Math.round(m * innerH);
        const filled = pct >= m - 0.01;
        return (
          <g key={i}>
            {/* right-side tick */}
            <line x1="54" y1={lineY} x2="62" y2={lineY}
              stroke={filled ? "#FFFFFF" : "#7BBFE0"} strokeWidth="1.5" strokeLinecap="round" opacity="0.85"/>
            {/* left-side short tick */}
            <line x1="10" y1={lineY} x2="16" y2={lineY}
              stroke={filled ? "#FFFFFF" : "#7BBFE0"} strokeWidth="1.5" strokeLinecap="round" opacity="0.85"/>
          </g>
        );
      })}

      {/* cap */}
      <rect x="26" y="0" width="20" height="8" rx="3" fill="#2490D0"/>

      {/* handle */}
      <path d="M50 30 Q66 30 66 48 Q66 60 56 62"
        fill="none" stroke="#A8D4F0" strokeWidth="5" strokeLinecap="round"/>

      {/* drop icon */}
      <text x="36" y="118" textAnchor="middle" fontSize="18">💧</text>
    </svg>
  );
}

