// ── usePersist hook ───────────────────────────────────────────
function usePersist(key, init) {
  const [val, setVal] = useState(() => {
    try { const s = memStorage.getItem(key); return s !== null ? JSON.parse(s) : init; }
    catch { return init; }
  });
  useEffect(() => { try { memStorage.setItem(key, JSON.stringify(val)); } catch {} }, [key, val]);
  return [val, setVal];
}

// Mantiene el fondo real de la página (html/body) igual al de la pantalla
// que esté activa en cada momento. Así, si el navegador llega a mostrar
// algo detrás del contenido (por ejemplo al "rebotar" en los extremos al
// hacer scroll), se ve el mismo fondo temático en vez de un espacio en
// blanco tipo ventana. Cada pantalla de tamaño completo debe llamar a
// este hook con su propio degradado.
function useSyncBodyBg(css) {
  useEffect(() => {
    const prev = document.body.style.background;
    document.body.style.background = css;
    document.body.style.backgroundAttachment = "fixed";
    document.documentElement.style.background = css;
    return () => {
      document.body.style.background = prev;
    };
  }, [css]);
}

// ── helpers ───────────────────────────────────────────────────
function todayKey() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}
// Day boundary for the Ingesta cards (kcal/macros/water) is 4:00 AM
// instead of midnight — logging at 1am still counts as "yesterday".
function ingestaDayKey() {
  const d = new Date(Date.now() - 4*60*60*1000);
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}
function fmtDate(iso) {
  const [y,m,d] = iso.split("-"); return `${d}/${m}/${y}`;
}
function getWeekDays() {
  const days = [], now = new Date();
  // Find Monday of current week
  const day = now.getDay(); // 0=Sun, 1=Mon...
  const monday = new Date(now);
  monday.setDate(now.getDate() - (day === 0 ? 6 : day - 1));
  for (let i = 0; i < 7; i++) {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    days.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`);
  }
  return days; // always Mon→Sun
}
const DAY_LABELS = ["D","L","M","X","J","V","S"];

